def game_score(points: str) -> str:
    # point counters for A and B
    a, b = 0, 0

    # mapping for display scores
    score_map = {0: "0", 1: "15", 2: "30", 3: "40"}

    for p in points:
        if p == 'A':
            a += 1
        elif p == 'B':
            b += 1
        else:
            # ignore any unexpected characters
            continue

        # Determine if the game has been won
        # Regular win condition (at least 4 points and at least 2 ahead)
        if (a >= 4 or b >= 4):
            if abs(a - b) >= 2:
                return f"Game {'A' if a > b else 'B'}"
            # No‑ad special case: deuce (both have 3) and one gets the next point
            if a == 4 and b == 3:
                return "Game A"
            if b == 4 and a == 3:
                return "Game B"

    # If no winner yet, produce current score string
    # Cap the displayed points at 3 (40)
    display_a = score_map.get(min(a, 3), "40")
    display_b = score_map.get(min(b, 3), "40")
    return f"{display_a}-{display_b}"
